<script>(()=>{const d=document.getElementById('homeDrop'),f=document.getElementById('homeFile'),c=document.getElementById('homeChoose'),m=document.getElementById('homeMsg'),token=document.querySelector('meta[name=csrf-token]');if(!d)return;c.onclick=()=>f.click();['dragenter','dragover'].forEach(x=>d.addEventListener(x,e=>{e.preventDefault();d.classList.add('dragover')}));['dragleave','drop'].forEach(x=>d.addEventListener(x,e=>{e.preventDefault();d.classList.remove('dragover')}));d.addEventListener('drop',e=>{if(e.dataTransfer.files[0])send(e.dataTransfer.files[0])});f.onchange=()=>{if(f.files[0])send(f.files[0])};async function send(file){m.hidden=false;m.textContent='در حال آماده‌سازی فایل…';const fd=new FormData();fd.append('source',file);try{const r=await fetch('/editor/upload',{method:'POST',headers:{'X-CSRF-TOKEN':token?.content||'','Accept':'application/json'},body:fd});const j=await r.json();if(!r.ok)throw new Error(j.message||'آپلود ناموفق بود');m.textContent='فایل آماده شد؛ در حال ورود به ویرایشگر…';location.href='/editor'}catch(e){m.textContent=navigator.onLine?e.message:'اتصال اینترنت در دسترس نیست؛ فایل شما در این مرحله ارسال نشده است.'}}})();</script>
